#!/usr/bin/env python3
"""
Round 125b (culprits-tiles-more), 2 October 2026. Upload after round124b_tiles.py.

- scripts/water_cases.py (new): named companies found or ruled to have
  taken or depleted water, each with its source, placed by Nominatim.

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/water_cases.py': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
